from ute_common_abstract_core import logger
from ..exceptions import CellRelatedParametersError
from ..ltecell import LteCell


class StartingCellConverter:
    """Starting Cell Converter"""

    def __init__(self, caller_name):
        """
        Basic initialization.
        :param caller_name:
        """
        self.caller_name = caller_name

    def get_starting_cell(self, starting_cell, starting_enb, starting_phy_cell):
        """
        Convert enb id & cell id into one hex value if necessary.
        :param starting_cell:
        :param starting_enb:
        :param starting_phy_cell:
        :return:
        """
        if isinstance(starting_cell, LteCell):
            cell_ids = starting_cell.get_cell_id()
            return self._convert_enb_and_cell_into_one_value(cell_ids['enb_id'], cell_ids['cell_id'])
        if starting_cell is None and starting_enb is not None and starting_phy_cell is not None:
            starting_cell = self._convert_enb_and_cell_into_one_value(starting_enb, starting_phy_cell)
            logger.debug(f'{self.caller_name}: {starting_enb=} and {starting_phy_cell=} have been converted into {starting_cell=}')
            return starting_cell
        else:
            self._check_starting_cell_requirements_conditions(starting_cell, starting_enb, starting_phy_cell)
            return starting_cell

    def _check_starting_cell_requirements_conditions(self, starting_cell, starting_enb, starting_phy_cell):
        if starting_cell is not None and (starting_enb is not None or starting_phy_cell is not None):
            raise CellRelatedParametersError('starting_cell cannot be provided with starting_enb or starting_phy_cell')
        elif (starting_enb is not None and starting_phy_cell is None) or \
                (starting_enb is None and starting_phy_cell is not None):
            raise CellRelatedParametersError('starting_enb and starting_phy_cell must be provided together')

    def _convert_enb_and_cell_into_one_value(self, enb, phy_cell):
        return int(enb) * pow(16, 2) + int(phy_cell)
